import * as D from './core/domain.js';
import * as DB from './core/store.js';
import {exportBackup,importBackup} from './core/backup.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.ledger}</svg>`;
globalThis.icon=icon;
const ui=createUI(icon),main=document.querySelector('#main'),navs=[['ledger','내역'],['budget','예산'],['savings','저축'],['manage','관리']];
let state,page='ledger',month=D.today().slice(0,7),view='list',ledgerTab='내역',manageTab='고정지출',categoryKind='expense',showArchived=false,query='',filtersOpen=false,bulk=false,limit=20,observer,editing=null,pending=null,loading=false,selected=new Set(),restoreFile=null,panelOrigin=null;
let filters={from:month+'-01',to:D.monthEnd(month),kinds:[],categories:[],payments:[],states:[]},toastTimer;
const types={credit_card:'신용카드',debit_card:'체크카드',cash:'현금',bank_transfer:'계좌이체',digital_wallet:'간편결제',other:'기타'},freqs={daily:'매일',weekly:'매주',monthly:'매월',yearly:'매년'};
const amount=n=>ui.money(D.won(n)),button=(label,action,primary=false,ico='')=>ui.button(label,action,primary,ico),action=(label,act,id,primary=false)=>`<button class="${primary?'primary':'button'}" data-action="${act}" data-id="${esc(id)}">${esc(label)}</button>`;
const cat=id=>D.find(state,'categories',id)?.name||'미분류',pay=id=>D.find(state,'paymentMethods',id)?.name||'미선택';
const empty=(message,cta='')=>`<div class="empty"><p>${esc(message)}</p>${cta}</div>`;
const field=(label,name,type='text',value='',placeholder='',readonly=false)=>ui.field(label,type,value,placeholder,readonly).replace('<input ','<input name="'+name+'" ').replace('</label>',name==='endDate'?'<button type="button" class="text-button" data-action="clear-end-date">종료일 해제</button></label>':'</label>');
function select(label,name,options,value=''){return `<label class="field ui-field"><span>${esc(label)}</span><select name="${name}" aria-label="${esc(label)}">${options.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;}
const pairs=o=>Object.entries(o);
function options(table,kind,previous){return [['','선택 안 함'],...state[table].filter(r=>(!r.archived||r.id===previous)&&(!kind||r.kind===kind)).map(r=>[r.id,r.name+(r.archived?' (보관)':'')])];}
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500);}
function error(message,fieldName=''){const host=document.querySelector('#form-error')||document.querySelector('#app-error');host.textContent=message;host.hidden=false;host.setAttribute('tabindex','-1');const fields=[...document.querySelectorAll('#edit-form .field')];const label=fields.find(l=>l.querySelector('span')?.textContent.trim().startsWith(fieldName)&&fieldName);const input=label?.querySelector('input,select,textarea');if(input){const details=input.closest('details');if(details)details.open=true;input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',host.id);input.focus();}else host.focus();}
function closeEditor(restore=true){destroyInputWidgets(document.querySelector('#inline-panel')||document.createElement('div'));document.querySelector('#inline-panel')?.closest('.inline-detail-row')?.remove();document.querySelector('#inline-panel')?.remove();editing=null;document.querySelectorAll('[aria-expanded=true].row-detail-button').forEach(e=>e.setAttribute('aria-expanded','false'));if(restore&&panelOrigin?.isConnected)panelOrigin.focus({preventScroll:true});if(restore)panelOrigin=null;}
function ask(message,fn){pending=fn;document.querySelector('#confirmation')?.remove();const el=document.createElement('section');el.id='confirmation';el.className='selection-bar';el.setAttribute('role','region');el.setAttribute('aria-label','작업 확인');el.innerHTML=`<span>${esc(message)}</span><div>${button('확인','confirm',true)}${button('취소','cancel-confirm')}</div>`;(document.querySelector('#inline-panel')||main.firstElementChild).insertAdjacentElement('beforebegin',el);el.scrollIntoView({block:'nearest'});el.querySelector('button').focus();}
function guarded(fn){if(editing?.dirty){ask('저장하지 않은 입력을 버릴까요?',()=>{closeEditor();fn();});return;}fn();}
async function commit(fn,{keep=false,expected=editing?.token||DB.token(state),after=null}={}){if(loading)return;loading=true;document.querySelectorAll('#edit-form button').forEach(b=>b.disabled=true);try{const defaults=keep?Object.fromEntries(['date','kind','categoryId','paymentMethodId'].map(k=>[k,document.querySelector('#edit-form').elements[k].value])):null;state=await DB.transact(expected,fn);closeEditor();selected.clear();bulk=false;render();notify('저장했습니다.');if(keep)openForm('transaction',null,defaults);if(after)after();}catch(e){error(e.message,e.field);if(e.conflict){state=await DB.readStore();const old=editing;ask('다른 탭의 변경을 확인한 뒤 다시 저장해야 합니다. 입력은 유지됩니다. 최신 데이터 기준으로 다시 확인할까요?',()=>{if(old)old.token=DB.token(state);notify('최신 데이터를 읽었습니다. 입력을 확인한 뒤 다시 저장해 주세요.');});}}finally{loading=false;document.querySelectorAll('#edit-form button').forEach(b=>b.disabled=false);}}
function monthBar(){return `<div class="month-row"><div class="month"><button class="icon-button" data-action="prev-month" aria-label="이전 달">${icon('arrowLeft')}</button><h2>${Number(month.slice(0,4))}년 ${Number(month.slice(5))}월</h2><button class="icon-button" data-action="next-month" aria-label="다음 달">${icon('arrow')}</button>${button('이번 달','this-month')}</div><span class="quiet">${esc(filters.from)} — ${esc(filters.to)}</span></div>`;}
function allRows(){return D.events(state,filters.from,filters.to,filters.states.includes('skipped'));}
function matching(rows){const q=query.trim().toLowerCase();return rows.filter(r=>(!q||`${r.title} ${r.memo}`.toLowerCase().includes(q))&&(!filters.kinds.length||filters.kinds.includes(r.kind))&&(!filters.categories.length||filters.categories.includes(r.categoryId||''))&&(!filters.payments.length||filters.payments.includes(r.paymentMethodId||''))&&(!filters.states.length||filters.states.includes(r.status)));}
const filtered=()=>matching(allRows());
function filterDescription(){return [query?'검색: '+query:'',...filters.kinds.map(k=>k==='income'?'수입':'지출'),...filters.categories.map(cat),...filters.payments.map(pay),...filters.states.map(s=>({confirmed:'확정',scheduled:'예정',skipped:'건너뜀'})[s])].filter(Boolean).join(' · ');}
const monthlyRows=()=>D.events(state,month+'-01',D.monthEnd(month));
function comparison(){const from=filters.from,to=filters.to,T=D.today(),end=from<=T&&T<to?T:to;let priorFrom,priorTo;if(from.endsWith('-01')&&to===D.monthEnd(from.slice(0,7))){const m=D.monthAdd(from.slice(0,7),-1);priorFrom=m+'-01';priorTo=m+'-'+String(Math.min(Number(end.slice(8)),Number(D.monthEnd(m).slice(8)))).padStart(2,'0');}else{const length=Math.round((Date.parse(to)-Date.parse(from))/86400000)+1;priorFrom=D.dayAdd(from,-length);priorTo=D.dayAdd(end,-length);}const previous=D.totals(matching(D.events(state,priorFrom,priorTo))).net,current=D.totals(matching(D.events(state,from,end))).net,diff=current-previous;return `${priorFrom}~${priorTo} 대비 ${diff>0n?'+':''}${D.won(diff)}원${previous>0n?' ('+(D.ratio(diff,previous)>0?'+':'')+D.ratio(diff,previous)+'%)':''}`;}
function summary(){const t=D.totals(filtered()),b=state.monthlyBudgets.find(b=>b.month===month),spent=D.totals(monthlyRows()).net;return `<section class="summary" aria-label="기간 요약"><div><span>지출</span>${amount(t.net)}<small>환불 ${D.won(t.refund)}원 · 예정 ${D.won(t.scheduled)}원</small></div><div><span>남은 금액</span>${amount(t.balance)}<small>수입 − 지출</small></div><div><span>남은 예산</span>${b?amount(BigInt(b.amount)-spent):'<strong>미설정</strong>'}<small class="budget-scope">${Number(month.slice(5))}월 전체 기준${b?' · '+D.won(b.amount)+'원':''}<br><a href="#budget">예산 설정 →</a></small></div></section>`;}
function checks(label,name,opts,values){return `<fieldset class="filter-options"><legend>${label}</legend>${opts.map(([v,t])=>`<label><input type="checkbox" name="${name}" value="${esc(v)}" ${values.includes(v)?'checked':''}> ${esc(t)}</label>`).join('')}</fieldset>`;}
function filterPanel(){return `<form id="filters-form" class="live-filters" ${filtersOpen?'':'hidden'}>${field('시작일','from','date',filters.from)}${field('종료일','to','date',filters.to)}${select('기간','period',[['custom','직접 지정'],['day','오늘'],['week','이번 주'],['month','이번 달']],'custom')}${checks('유형','kinds',[['expense','지출'],['income','수입']],filters.kinds)}${checks('카테고리','categories',[['','미분류'],...state.categories.map(c=>[c.id,c.name])],filters.categories)}${checks('결제수단','payments',[['','미선택'],...state.paymentMethods.map(p=>[p.id,p.name])],filters.payments)}${checks('조회 대상','states',[['confirmed','확정'],['scheduled','예정'],['skipped','건너뜀']],filters.states)}<div class="inline-form-actions">${button('적용','apply-filters',true)}${button('초기화','reset-filters')}</div></form>`;}
function row(r){const refund=r.eventType==='refund',skipped=r.eventType==='skipped';return `<tr data-row="${esc(r.id)}" class="${selected.has(r.id)?'row-selected':''}"><td><time datetime="${r.date}">${r.date.slice(5).replace('-','.')}</time></td><td>${esc(cat(r.categoryId))}</td><td class="ledger-title">${esc(r.title)}${refund?' <span class="pill">환불</span>':skipped?' <span class="pill">건너뜀</span>':r.status==='scheduled'?' <span class="pill">예정</span>':''}<small class="mobile-meta"><span class="mobile-category">${esc(cat(r.categoryId))} · </span>${esc(pay(r.paymentMethodId))}</small></td><td class="ledger-money ${r.kind==='income'||refund?'income':''}">${r.kind==='income'||refund?'+':'−'}${D.won(r.amount)}<small>원</small></td><td>${r.kind==='income'?'—':esc(pay(r.paymentMethodId))}</td><td>${bulk?`<input type="checkbox" aria-label="${esc(r.title)} 선택" ${selected.has(r.id)?'checked':''} ${skipped?'disabled':''}>`:`<button class="row-detail-button" aria-label="${esc(r.title)} 자세히 보기" aria-expanded="false">${icon('arrow')}</button>`}</td></tr>`;}
function ledgerTable(){const rows=filtered(),loaded=rows.slice(0,limit);return `${bulk?`<div class="selection-bar"><strong>${selected.size}건 선택</strong><span>현재 표시된 ${loaded.filter(r=>r.eventType!=='skipped').length}건</span><div>${button('조회 결과 전체 '+rows.filter(r=>r.eventType!=='skipped').length+'건 선택','select-results')}<button class="primary" data-action="delete-selected" ${selected.size?'':'disabled'}>선택 삭제</button>${button('취소','bulk')}</div></div>`:''}<div class="ledger-table-wrap"><table class="ledger-table"><caption class="sr-only">거래 내역</caption><thead><tr><th>날짜</th><th>카테고리</th><th>내역명</th><th>금액</th><th>결제수단</th><th>${bulk?'<input type="checkbox" data-action="select-all" aria-label="현재 표시된 내역 선택">':'<span class="sr-only">상세</span>'}</th></tr></thead><tbody>${loaded.map(row).join('')}</tbody></table></div>${rows.length?'':empty(state.transactions.length?'조건에 맞는 내역이 없습니다.':'아직 기록한 내역이 없습니다.',button('내역 추가','add',true)+button('조건 초기화','reset-filters'))}<div id="list-end" class="list-end" aria-live="polite">${rows.length>limit?`${limit} / ${rows.length}건`:`${rows.length}건 · 마지막 내역입니다`}</div>`;}
function calendar(){const first=month+'-01',offset=(new Date(first+'T00:00:00Z').getUTCDay()+6)%7,start=D.dayAdd(first,-offset),rows=filtered();return `<div class="calendar"><div class="calendar-week">${['월','화','수','목','금','토','일'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-days">${Array.from({length:42},(_,i)=>{const d=D.dayAdd(start,i),t=D.totals(rows.filter(r=>r.date===d));return `<button data-day="${d}" class="${d===D.today()?'current':''} ${d.slice(0,7)!==month?'muted-day':''}"><span><span class="sr-only">${d.slice(0,7)} </span>${Number(d.slice(8))}</span>${t.income?`<small class="income">+${D.won(t.income)}</small>`:''}${t.net?`<small class="${t.net<0n?'income':''}" aria-label="${t.net<0n?'환불 초과':'지출'} ${D.won(t.net<0n?-t.net:t.net)}원">${t.net<0n?'+':'−'}${D.won(t.net<0n?-t.net:t.net)}</small>`:''}${t.scheduled?'<small>예정</small>':''}</button>`}).join('')}</div></div>`;}
function statsTable(title,rows,headers){return `<section class="stats-section"><h3>${title}</h3><div class="data-table-wrap" tabindex="0"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function financeChart(rows,label){const values=rows.flatMap(r=>r.slice(1).map(n=>BigInt(n.replaceAll(',',''))));const max=values.reduce((m,n)=>{n=n<0n?-n:n;return n>m?n:m;},1n);return `<div class="chart-legend"><span>수입</span><span>순지출 · 환불 초과는 기준선 아래</span></div><div class="bar-chart" tabindex="0" role="img" aria-label="${label}. 같은 값의 표가 이어집니다."><div class="live-chart-bars">${rows.map(r=>`<div class="live-chart-day"><span class="chart-zero"></span>${[1,2].map(i=>{const v=BigInt(r[i].replaceAll(',','')),h=Number((v<0n?-v:v)*450n/max)/10;return `<span class="live-bar ${i===1?'bar-income':'bar-expense'}" style="height:${h}%;${v<0n?'top':'bottom'}:50%" title="${r[0]} ${i===1?'수입':'순지출'} ${r[i]}원"></span>`;}).join('')}<small>${r[0].length===7?r[0].slice(5):Number(r[0].slice(8))}</small></div>`).join('')}</div></div>`;}
function statistics(){const rows=filtered(),total=D.totals(rows),days=[];for(let d=filters.from;d<=filters.to;d=D.dayAdd(d,1)){const t=D.totals(rows.filter(r=>r.date===d));days.push([d,D.won(t.income),D.won(t.net)]);}const groups=[...new Set(rows.filter(r=>r.kind==='expense').map(r=>r.categoryId))].map(id=>{const t=D.totals(rows.filter(r=>r.categoryId===id));return [esc(cat(id)),D.won(t.net),D.won(t.refund),D.ratio(t.expense,total.expense)===null?'—':D.ratio(t.expense,total.expense)+'%'];});const methods=[...new Set(rows.filter(r=>r.kind==='expense').map(r=>r.paymentMethodId))].map(id=>{const rr=rows.filter(r=>r.kind==='expense'&&r.paymentMethodId===id),t=D.totals(rr);return [esc(pay(id)),D.won(t.net),D.won(t.refund),rr.filter(r=>r.status==='confirmed'&&r.eventType==='transaction').length];});const trend=Array.from({length:12},(_,i)=>{const m=D.monthAdd(month,i-11),t=D.totals(matching(D.events(state,m+'-01',D.monthEnd(m))));return [m,D.won(t.income),D.won(t.net)];});return `<div class="statistics"><p class="comparison">${comparison()}</p>${filterDescription()?`<p class="filter-scope">${esc(filterDescription())} ${button('초기화','reset-filters')}</p>`:''}${!rows.length?empty('해당 기간의 데이터가 없습니다.'):''}<h3>기간별 지출</h3>${financeChart(days,'일별 수입과 순지출')}${statsTable('요약',[[D.won(total.income),D.won(total.net),D.won(total.refund),D.won(total.balance)]],['수입','순지출','환불','차액'])}${statsTable('카테고리별 · 환불 전 지출 비중',groups,['카테고리','순지출','환불','비중'])}${statsTable('결제수단별',methods,['결제수단','순사용액','환불','사용 횟수'])}<details><summary>일별 금액 표</summary>${statsTable('일별',days,['날짜','수입','순지출'])}</details>${financeChart(trend,'최근 12개월 수입과 순지출')}${statsTable('최근 12개월',trend,['월','수입','순지출'])}</div>`;}
function resultContent(){const t=D.totals(filtered());return `${query||Object.values(filters).some(v=>Array.isArray(v)&&v.length)?`<p class="result-summary">필터 결과 ${filtered().length}건 · 순지출 ${D.won(t.net)}원 · 예정 ${D.won(t.scheduled)}원 ${button('초기화','reset-filters')}</p><p class="filter-scope">${esc(filterDescription())}</p>`:''}${view==='calendar'?calendar():ledgerTable()}`;}
function refreshResults(){closeEditor();observer?.disconnect();document.querySelector('.summary').outerHTML=summary();document.querySelector('#ledger-results').innerHTML=resultContent();document.querySelector('[data-action=bulk]')?.setAttribute('aria-pressed',String(bulk));setupScroll();}
function ledger(){return `${ui.heading('내역',button('내역 추가','add',true,'plus'))}${monthBar()}${summary()}<section class="card ledger-card"><div class="card-tabs">${ui.tabs(['내역','통계'],ledgerTab,'ledger-tab')}</div>${ledgerTab==='통계'?statistics():`<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="내역 검색" placeholder="내역명·메모 검색" value="${esc(query)}"></label><button class="button compact" data-action="filters" aria-expanded="${filtersOpen}">${icon('filter')}<span>필터</span></button><div class="view-toggle"><button data-view="list" class="${view==='list'?'selected':''}" aria-label="목록 보기">${icon('ledger')}</button><button data-view="calendar" class="${view==='calendar'?'selected':''}" aria-label="달력 보기">${icon('calendar')}</button></div><button class="button bulk-toggle" data-action="bulk" aria-label="여러 내역 삭제" aria-pressed="${bulk}">${icon('trash')}</button></div>${filterPanel()}<div id="ledger-results">${resultContent()}</div>`}</section>`;}

function budget(){const b=state.monthlyBudgets.find(b=>b.month===month),rows=monthlyRows(),t=D.totals(rows),limits=state.categoryBudgets.filter(b=>b.month===month);return `${ui.heading('예산',button('예산 설정','budget-form',true,'plus'))}${monthBar()}<section class="budget-hero"><div><span class="eyebrow">남은 예산</span><h2>${b?amount(BigInt(b.amount)-t.net):'미설정'}</h2></div><div class="budget-hero-progress"><div><span>${D.won(t.net)}원 사용</span><strong>${b&&D.ratio(t.net,b.amount)!==null?D.ratio(t.net,b.amount)+'%':'—'}</strong></div>${ui.progress(b?D.ratio(t.net,b.amount)||0:0)}<div><span>예정 ${D.won(t.scheduled)}원</span><span>${b?'전체 '+D.won(b.amount)+'원':''}</span></div></div></section><div class="section-heading"><h2>카테고리별 예산</h2><div>${button('다른 달에서 복사','budget-copy')}${b?button('예산 삭제','budget-delete'):''}</div></div>${limits.length?`<div class="cards-grid">${limits.map(l=>{const used=D.totals(rows.filter(r=>r.categoryId===l.categoryId)).net;return `<section class="card category-budget"><h3>${esc(cat(l.categoryId))}</h3>${amount(used)}<p>한도 ${D.won(l.amount)}원 · 남은 금액 ${D.won(BigInt(l.amount)-used)}원</p>${ui.progress(D.ratio(used,l.amount)||0)}<div class="progress-caption"><span>${D.ratio(used,l.amount)===null?'—':D.ratio(used,l.amount)+'%'}</span>${action('내역 보기','category-ledger',l.categoryId)}</div></section>`;}).join('')}</div>`:empty('카테고리 한도를 설정하면 사용액을 함께 볼 수 있습니다.')}`;}
function goalCard(g){const balance=D.goalBalance(state,g.id),pct=D.ratio(balance,g.targetAmount),status=balance>=BigInt(g.targetAmount)?'달성':g.archived?'보관':D.today()>g.targetDate?'기한 경과':'진행 중';return `<button class="card goal-card" data-goal="${g.id}"><div class="goal-art blue"><span class="goal-tag">${status}</span><div class="sun"></div><div class="sea sea-back"></div><div class="sea"></div></div><div class="goal-body"><h3>${esc(g.name)}</h3>${amount(balance)}<span class="quiet"> / ${D.won(g.targetAmount)}원</span>${ui.progress(pct)}<div class="progress-caption"><strong>${pct}%</strong><span>${g.targetDate}까지${g.archived?' · 보관':''}</span></div></div></button>`;}
function savings(){const active=state.savingsGoals.filter(g=>!g.archived&&D.goalBalance(state,g.id)<BigInt(g.targetAmount)),done=state.savingsGoals.filter(g=>D.goalBalance(state,g.id)>=BigInt(g.targetAmount)),archived=state.savingsGoals.filter(g=>g.archived&&D.goalBalance(state,g.id)<BigInt(g.targetAmount));const total=state.savingsGoals.reduce((n,g)=>n+D.goalBalance(state,g.id),0n);return `${ui.heading('저축 목표',button('목표 만들기','goal-form',true,'plus'))}<div class="saving-banner"><span class="plant-large">${icon('savings')}</span><div><span class="eyebrow">총 저축액</span><h2>${amount(total)}</h2></div></div><div class="section-heading"><h2>나의 저축 목표 <span class="count">${active.length}</span></h2></div><div class="cards-grid goals">${active.map(goalCard).join('')}</div>${!active.length?empty('진행 중인 목표가 없습니다.',button('목표 만들기','goal-form')):''}<details class="completed-goals"><summary><h2>완료된 목표 <span class="count">${done.length}</span></h2>${icon('arrow','completed-chevron')}</summary><div class="cards-grid goals">${done.map(goalCard).join('')}</div></details>${archived.length?`<details class="archived-goals completed-goals"><summary><h2>보관된 목표 <span class="count">${archived.length}</span></h2>${icon('arrow','completed-chevron')}</summary><div class="cards-grid goals">${archived.map(goalCard).join('')}</div></details>`:''}`;}
function manage(){let body='';if(manageTab==='고정지출'){const rules=state.recurrenceRules.filter(r=>r.status!=='deleted');body=`<div class="section-title"><h2>고정지출</h2>${button('고정지출 추가','rule-form',true,'plus')}</div>${rules.map(r=>{const v=D.find(state,'recurrenceVersions',r.currentVersionId);return `<button class="transaction" data-rule="${r.id}"><span class="category-icon blue">${icon('repeat')}</span><span class="transaction-title"><strong>${esc(v.title)}</strong><small>${freqs[v.frequency]} · ${r.status==='paused'?'중지':state.recurrencePauses.some(p=>p.ruleId===r.id&&p.resumeOn>D.today())?'재개 예정':'활성'} · ${v.anchorDate}부터</small></span><span class="transaction-amount">${D.won(v.amount)}원</span>${icon('arrow')}</button>`;}).join('')}${!rules.length?empty('등록된 고정지출이 없습니다.'):''}`;}
else if(manageTab==='카테고리'){body=`<div class="section-title"><h2>카테고리</h2>${button('카테고리 추가','category-form',true,'plus')}</div><div class="mini-tabs">${action('지출','category-kind','expense',categoryKind==='expense')}${action('수입','category-kind','income',categoryKind==='income')}${button(showArchived?'활성 항목':'보관 항목','archive-toggle')}</div><div class="category-grid">${state.categories.filter(c=>c.kind===categoryKind&&c.archived===showArchived).map(c=>`<button data-category="${c.id}"><span class="category-icon blue">${icon('bag')}</span><strong>${esc(c.name)}</strong>${icon('arrow')}</button>`).join('')}</div>`;}
else if(manageTab==='결제수단'){body=`<div class="section-title"><h2>결제수단</h2>${button('결제수단 추가','payment-form',true,'plus')}</div><div class="mini-tabs">${button(showArchived?'활성 항목':'보관 항목','archive-toggle')}</div><div class="cards-grid payment-cards">${state.paymentMethods.filter(p=>p.archived===showArchived).map((p,i)=>{const rows=monthlyRows().filter(r=>r.paymentMethodId===p.id&&r.kind==='expense'),t=D.totals(rows);return `<button class="payment-card ${['forest','navy','clay'][i%3]}" data-payment="${p.id}">${icon('budget')}<span>${types[p.type]}</span><h3>${esc(p.name)}</h3><p class="payment-date">${p.type==='credit_card'?(p.paymentDay?'결제일 · 매월 '+p.paymentDay+'일':'결제일 미설정'):p.type==='debit_card'?'즉시 출금':'결제일 해당 없음'}</p><small>${month} 순사용액</small>${amount(t.net)}<span>사용 내역 보기 →</span></button>`;}).join('')}</div>${!state.paymentMethods.length?empty('결제수단을 추가하면 카드별 내역을 모아 볼 수 있습니다.'):''}`;}
else body=`<div class="section-title"><h2>백업·복원</h2></div><div class="info-note">데이터는 현재 브라우저에만 저장됩니다. 기기 변경이나 브라우저 데이터 삭제 전에 파일로 내보내 주세요. 기기 간 동기화는 제공하지 않습니다.</div><div class="backup-grid"><section><h3>내 기록 내보내기</h3><p>모든 기록과 설정을 JSON 파일로 저장합니다.</p>${button('JSON 내보내기','export',true,'download')}${state.recovery?button('복원 직전 백업 다운로드','recovery'):''}</section><section><h3>백업 가져오기</h3><p>파일 검증과 미리보기 후 현재 데이터를 전체 대체합니다.</p><label class="field"><span>JSON 백업 파일</span><input id="import-file" type="file" accept=".json,application/json"></label><div id="import-message" role="status"></div></section></div><section class="info-note"><strong>앱 설치와 오프라인</strong><p id="install-help">브라우저의 앱 설치 메뉴 또는 iPhone의 공유 → 홈 화면에 추가를 사용할 수 있습니다. 처음 접속한 뒤 준비가 끝나면 오프라인에서도 다시 열 수 있습니다.</p><button id="install-button" class="button" hidden>앱 설치</button><span id="offline-status" role="status"></span></section>`;
return `${ui.heading('관리')}<section class="card management">${ui.tabs(['고정지출','카테고리','결제수단','백업·복원'],manageTab,'manage-tab')}<div class="management-body">${body}</div></section>`;}
function render(){observer?.disconnect();destroyInputWidgets(main);editing=null;const active=document.activeElement,attr=['data-ledger-tab','data-manage-tab','data-view','data-action'].find(k=>active?.hasAttribute(k)),focus=attr?`[${attr}="${CSS.escape(active.getAttribute(attr))}"]`:null;document.querySelector('#navigation').innerHTML=navs.map(([id,label])=>`<a href="#${id}" class="nav-item ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${page===id?'<i></i>':''}</a>`).join('');main.innerHTML=`<div id="app-error" class="form-error" role="alert" hidden></div>${!state.meta.onboardingSeen?`<section class="onboarding info-note">이 브라우저에 기록을 저장합니다. 기기 간 동기화는 없으며 데이터 삭제 전에 JSON 백업이 필요합니다. ${button('확인했어요','onboard')}</section>`:''}${page==='ledger'?ledger():page==='budget'?budget():page==='savings'?savings():manage()}`;initInputWidgets(main);if(focus)main.querySelector(focus)?.focus({preventScroll:true});const all=main.querySelector('[data-action=select-all]');if(all){const eligible=filtered().slice(0,limit).filter(r=>r.eventType!=='skipped');all.checked=eligible.length>0&&eligible.every(r=>selected.has(r.id));all.indeterminate=selected.size>0&&!all.checked;}setupScroll();globalThis.updateInstallUI?.();}
function setupScroll(){const end=document.querySelector('#list-end');if(!end||bulk)return;observer=new IntersectionObserver(es=>{if(!es.some(e=>e.isIntersecting))return;const rows=filtered();if(limit>=rows.length)return;const next=rows.slice(limit,limit+20);limit+=20;document.querySelector('.ledger-table tbody').insertAdjacentHTML('beforeend',next.map(row).join(''));end.textContent=rows.length>limit?`${limit} / ${rows.length}건`:`${rows.length}건 · 마지막 내역입니다`;},{rootMargin:'80px'});observer.observe(end);}
function panel(title,body,footer='',anchor=null,compact=false){const origin=anchor?.matches('tr')?anchor.querySelector('button'):anchor||((document.activeElement?.closest('#inline-panel'))?panelOrigin:document.activeElement);closeEditor(false);panelOrigin=origin;const el=document.createElement('section');el.id='inline-panel';el.className=`panel inline-panel${compact?' transaction-editor':''}`;el.setAttribute('aria-label',title);el.innerHTML=`<div id="panel-content">${compact?'':`<div class="panel-header"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="닫기">${icon('close')}</button></div>`}<div class="panel-body">${body}</div>${footer?`<div class="panel-footer">${footer}</div>`:''}</div>`;
 if(anchor?.matches('tr')){const tr=document.createElement('tr');tr.className='inline-detail-row';const td=document.createElement('td');td.colSpan=[...anchor.closest('table').querySelectorAll('th')].filter(x=>getComputedStyle(x).display!=='none').length;tr.append(td);td.append(el);anchor.after(tr);anchor.querySelector('.row-detail-button')?.setAttribute('aria-expanded','true');}else if(anchor?.isConnected){anchor.after(el);el.classList.add('anchored-panel');}else{const toolbar=document.querySelector('.ledger-card .toolbar');if(page==='ledger'&&toolbar)toolbar.after(el);else{const host=document.querySelector('.management-body')||main;const heading=host.querySelector('.section-title,.heading');if(heading)heading.after(el);else host.prepend(el);}}el.querySelector('input:not([readonly]),select')?.focus({preventScroll:true});el.scrollIntoView({block:'nearest'});initInputWidgets(el);return el;}
function findRow(id){return document.querySelector(`[data-row="${CSS.escape(id)}"]`);}
function detail(id){const r=allRows().find(r=>r.id===id)||state.transactions.find(t=>t.id===id)||state.refunds.find(t=>t.id===id);if(!r)return;if(editing?.detailId===id){closeEditor();return;}if(r.eventType==='skipped'){panel('건너뛴 회차',`<p>${esc(r.title)} · ${r.date}</p>`,action('건너뜀 취소','unskip',r.id),findRow(id));return;}
 const refund=r.eventType==='refund'||Object.hasOwn(r,'transactionId'),idActual=refund?r.transactionId:r.id,t=refund?D.find(state,'transactions',idActual):r,refunds=state.refunds.filter(x=>x.transactionId===idActual),total=D.sum(refunds);const body=`<dl class="transaction-facts memo-only"><dt>메모</dt><dd class="fact-memo">${esc(r.memo||'없음')}</dd></dl>${refund?`<p>환불일 ${r.date} · ${D.won(r.amount)}원</p>`:''}${refunds.length&&!refund?`<div class="refund-history"><span>환불 합계 ${D.won(total)}원</span>${refunds.map(x=>`<div>${x.date} · ${D.won(x.amount)}원 ${action('수정','refund-edit',x.id)}${action('삭제','refund-delete',x.id)}</div>`).join('')}</div>`:''}`;
 const el=panel('내역 상세',body,refund?`${action('삭제','refund-delete',r.id)}${action('수정','refund-edit',r.id)}${action('원거래','transaction-detail',idActual)}`:`${action('삭제','transaction-delete',idActual)}${action('수정','transaction-edit',idActual)}${t.kind==='expense'&&t.status==='confirmed'&&total<BigInt(t.amount)?action('환불','refund-form',idActual):''}`,findRow(id),true);el.classList.add('transaction-detail');el.classList.remove('transaction-editor');editing={detailId:id,dirty:false};}
function namedDetail(table,id){const r=D.find(state,table,id);if(!r)return;const isGoal=table==='savingsGoals',isPayment=table==='paymentMethods';let body=`<p>${esc(r.name)}</p>`,footer='';if(isGoal){const entries=state.savingsEntries.filter(e=>e.goalId===id).sort((a,b)=>b.date.localeCompare(a.date));body=`<div class="detail-intro">${amount(D.goalBalance(state,id))}<span>목표 ${D.won(r.targetAmount)}원 · ${r.targetDate}</span></div>${entries.length?entries.map(e=>`<div class="entry-line"><span>${e.date} · ${e.kind==='deposit'?'저축':'인출'} · ${D.won(e.amount)}원<br><small>${esc(e.memo)}</small></span>${!r.archived?`${action('수정','entry-edit',e.id)}${action('삭제','entry-delete',e.id)}`:''}</div>`).join(''):empty('아직 저축 기록이 없습니다.')}`;footer=r.archived?'':`${action('목표 수정','goal-edit',id)}${action('저축 기록','entry-form',id,true)}`;}
 if(isPayment){const rows=monthlyRows().filter(t=>t.paymentMethodId===id&&t.kind==='expense'),t=D.totals(rows);body=`<dl><dt>유형</dt><dd>${types[r.type]}</dd><dt>결제일</dt><dd>${r.paymentDay?'매월 '+r.paymentDay+'일':r.type==='debit_card'?'즉시 출금':'미설정'}</dd><dt>${month} 순사용액</dt><dd>${D.won(t.net)}원</dd><dt>환불액</dt><dd>${D.won(t.refund)}원</dd></dl>${button('이 카드 내역 보기','payment-ledger',true)}${!rows.length?empty('해당 월의 사용 내역이 없습니다.'):rows.slice(0,20).map(t=>`<button class="transaction" data-action="transaction-detail" data-id="${t.eventType==='refund'?t.transactionId:t.id}"><span class="transaction-title"><strong>${esc(t.title)}</strong><small>${t.date}${t.eventType==='refund'?' · 환불':''}</small></span>${amount(t.amount)}</button>`).join('')}`;footer=action('수정','payment-edit',id);}
 if(table==='categories')footer=action('수정','category-edit',id);
 footer+=action(r.archived?'복원':'보관','named-archive',table+':'+id);if(!D.referenced(state,table,id))footer+=action('삭제','named-delete',table+':'+id);panel(r.name,body,footer,document.querySelector(`[data-${isGoal?'goal':isPayment?'payment':'category'}="${CSS.escape(id)}"]`));editing={detailId:id,table,dirty:false,token:DB.token(state)};}
function ruleDetail(id){const r=D.find(state,'recurrenceRules',id),v=D.find(state,'recurrenceVersions',r.currentVersionId);const occurrences=state.recurrenceOccurrences.filter(o=>o.ruleId===id).sort((a,b)=>b.originalDate.localeCompare(a.originalDate));panel(v.title,`<p>${freqs[v.frequency]} · ${v.anchorDate}부터 ${v.endDate||'계속'} · ${r.status==='active'?'활성':'중지'}</p>${amount(v.amount)}<h3>회차 내역</h3>${occurrences.slice(0,100).map(o=>{const t=state.transactions.find(t=>t.occurrenceId===o.id);return `<div class="entry-line"><span>${o.originalDate} · ${o.state==='skipped'?'건너뜀':o.state==='suppressed'?'중지로 제거':t.status==='confirmed'?'확정':'예정'}${o.individuallyModified?' · 개별 수정':''}</span>${t?action('상세','transaction-detail',t.id):o.state==='skipped'?action('건너뜀 취소','unskip',o.id):''}</div>`;}).join('')||empty('생성된 회차가 없습니다.')}`,`${action('수정','rule-edit',id)}${r.status==='active'?action('중지','rule-stop',id):action('재개','rule-resume',id)}${action('삭제','rule-delete',id)}`,document.querySelector(`[data-rule="${CSS.escape(id)}"]`));}
function openForm(type,id=null,context=null){let old={},title='',body='',compact=false,footer=true;if(type==='transaction'){old=id?.startsWith('virtual:')?allRows().find(r=>r.id===id):id?D.find(state,'transactions',id):(context||{});old=old||{};const locked=id&&state.refunds.some(r=>r.transactionId===id);title=id?'내역 수정':'내역 추가';compact=true;body=`${field('날짜','date','date',old.date||D.today(),'',locked)}${select('수입/지출','kind',[['expense','지출'],['income','수입']],old.kind||'expense')}${field('내역명','title','text',old.title||'','내역명 입력')}${field('금액','amount','number',old.amount||'','0원',locked)}${select('카테고리','categoryId',options('categories',old.kind||'expense',old.categoryId),old.categoryId||'')}${select('결제수단','paymentMethodId',options('paymentMethods',null,old.paymentMethodId),old.paymentMethodId||'')}`;}
 if(type==='refund'){old=id?D.find(state,'refunds',id):{};const parent=D.find(state,'transactions',old.transactionId||context);D.assert(parent,'원거래를 찾을 수 없습니다.');const max=BigInt(parent.amount)-D.sum(state.refunds.filter(r=>r.transactionId===parent.id&&r.id!==id));title=id?'환불 수정':'환불';compact=true;body=`${field('내역명','originalTitle','text',parent.title,'',true)}${field('환불 가능액','available','text',D.won(max)+'원','',true)}${field('환불일','date','date',old.date||D.today())}${field('환불 금액','amount','number',old.amount||'','0원')}`;context=parent.id;}
 if(type==='budget'){title='월 예산 설정';old=state.monthlyBudgets.find(b=>b.month===month)||{};body=`${field('전체 예산','amount','number',old.amount??'','0원')}<details class="budget-limits"><summary>카테고리별 한도 설정 (선택)</summary><p class="form-hint">카테고리 한도는 선택 입력입니다. 빈칸은 한도 없음, 0은 사용 허용액 0원입니다.</p>${state.categories.filter(c=>c.kind==='expense'&&(!c.archived||state.categoryBudgets.some(b=>b.month===month&&b.categoryId===c.id))).map(c=>field(c.name+(c.archived?' (보관)':''),'limit-'+c.id,'number',state.categoryBudgets.find(b=>b.month===month&&b.categoryId===c.id)?.amount??'')).join('')}</details>`;}
 if(type==='budget-copy'){title='다른 달 예산 복사';body=field('가져올 월','source','month',D.monthAdd(month,-1))+`<p>대상: ${month}. 현재 월 설정을 대체합니다. 보관 카테고리 한도는 제외합니다.</p>`;}
 if(type==='goal'){title=id?'목표 수정':'목표 만들기';old=id?D.find(state,'savingsGoals',id):{};body=field('목표명','name','text',old.name||'')+field('목표 금액','targetAmount','number',old.targetAmount||'')+field('시작일','startDate','date',old.startDate||D.today())+field('목표일','targetDate','date',old.targetDate||D.dayAdd(D.today(),30));}
 if(type==='entry'){title=id?'저축 기록 수정':'저축·인출 기록';old=id?D.find(state,'savingsEntries',id):{};context=old.goalId||context;body=select('유형','kind',[['deposit','저축'],['withdrawal','인출']],old.kind||'deposit')+field('날짜','date','date',old.date||D.today())+field('금액','amount','number',old.amount||'');}
 if(type==='category'){title=id?'카테고리 수정':'카테고리 추가';old=id?D.find(state,'categories',id):{};body=field('이름','name','text',old.name||'')+select('유형','kind',[['expense','지출'],['income','수입']],old.kind||categoryKind);}
 if(type==='payment'){title=id?'결제수단 수정':'결제수단 추가';old=id?D.find(state,'paymentMethods',id):{};body=field('이름','name','text',old.name||'')+select('유형','type',pairs(types),old.type||'other')+`<div id="payment-day-field" ${old.type==='credit_card'?'':'hidden'}>${select('결제일','paymentDay',[['','미설정'],...Array.from({length:31},(_,i)=>[String(i+1),`${i+1}일`])],String(old.paymentDay||''))}</div>`;}
 if(type==='rule'){title=id?'고정지출 수정':'고정지출 추가';old=id?D.find(state,'recurrenceVersions',D.find(state,'recurrenceRules',id).currentVersionId):{};body=field('내역명','title','text',old.title||'')+field('금액','amount','number',old.amount||'')+select('반복 주기','frequency',pairs(freqs),old.frequency||'monthly')+field('시작일','anchorDate','date',old.anchorDate||D.today())+field('종료일 · 선택','endDate','date',old.endDate||'')+select('카테고리','categoryId',options('categories','expense',old.categoryId),old.categoryId||'')+select('결제수단','paymentMethodId',options('paymentMethods',null,old.paymentMethodId),old.paymentMethodId||'');}
 if(type==='resume'){title='고정지출 재개';body=field('재개일','date','date',D.today());}
 const memo=['transaction','refund','entry','rule'].includes(type)?`<label class="field inline-memo"><span class="sr-only">메모</span><input name="memo" type="text" placeholder="메모 입력 (선택)" value="${esc(old.memo||'')}" maxlength="1000"></label>`:'';
 const actions=`<button class="primary" type="submit">${type==='transaction'&&!id?'추가':type==='refund'?'환불 저장':'저장'}</button>${button('취소','close')}`;
 const source=panelOrigin?.isConnected?panelOrigin:null;const el=panel(title,`<form id="edit-form" novalidate>${body}<div class="inline-form-actions">${memo}${actions}</div><div id="form-error" class="form-error" role="alert" hidden></div></form>`,'',type==='transaction'&&id?findRow(id):type==='refund'?findRow(context):source,compact);if(type==='refund')el.classList.add('refund-editor');
 editing={type,id,context,token:DB.token(state),dirty:false};if(type==='transaction'&&!id)el.querySelector('[name=title]')?.focus({preventScroll:true});
 if(type==='transaction'){const form=el.querySelector('form');if(old.kind==='income')form.elements.paymentMethodId.disabled=true;if(id&&(old.occurrenceId||state.refunds.some(r=>r.transactionId===id)))form.elements.kind.disabled=true;if(id&&state.refunds.some(r=>r.transactionId===id))form.elements.date.disabled=true;}
 for(const input of el.querySelectorAll('input[data-date]')){if(input.name==='date'&&['refund','entry'].includes(type))input._flatpickr?.set('maxDate',D.today());if(type==='refund'&&input.name==='date')input._flatpickr?.set('minDate',D.find(state,'transactions',context).date);}
}
const number=(v,label='금액',zero=false)=>{D.assert(typeof v==='string'&&/^\d[\d,]*$/.test(v),`${label}을 숫자로 입력해 주세요.`,label);const n=Number(v.replaceAll(',',''));D.assert(Number.isSafeInteger(n)&&n>=(zero?0:1)&&n<=999999999,`${label}은 ${zero?'0':'1'}~999,999,999원입니다.`,label);return n;};
function formData(){const form=document.querySelector('#edit-form');return Object.fromEntries([...form.elements].filter(e=>e.name).map(e=>[e.name,String(e.value).trim()]));}
function previewSave(fn,message,expected){try{const copy=structuredClone(state);fn(copy,D.today());D.validate(copy);const T=D.today();ask(message,()=>commit((s,t)=>{D.assert(t===T,'날짜가 바뀌었습니다. 미리보기를 다시 확인해 주세요.');fn(s,t);},{expected}));}catch(e){error(e.message,e.field);}}
async function saveForm(){if(!editing)return;const e=editing,f=formData(),expected=e.token;try{
 let fn;
 if(e.type==='transaction'){const data={kind:f.kind,date:f.date,title:f.title,amount:number(f.amount),categoryId:f.categoryId||null,paymentMethodId:f.kind==='income'?null:f.paymentMethodId||null,memo:f.memo};fn=(s,T)=>{let id=e.id;if(id?.startsWith('virtual:')){const v=D.projected(s,f.date<filters.from?f.date:filters.from,filters.to).find(r=>r.id===id)||allRows().find(r=>r.id===id);D.assert(v,'예정 회차가 변경되었습니다.');id=D.materialize(s,v,T).id;}D.saveTransaction(s,data,id,T);};await commit(fn,{expected,keep:!e.id});return;}
 if(e.type==='refund'){const data={transactionId:e.context,date:f.date,amount:number(f.amount,'환불 금액'),memo:f.memo};fn=s=>D.saveRefund(s,data,e.id);}
 if(e.type==='budget'){const n=number(f.amount,'전체 예산',true),limits=Object.entries(f).filter(([k,v])=>k.startsWith('limit-')&&v!=='').map(([k,v])=>({categoryId:k.slice(6),amount:number(v,'카테고리 한도',true)}));fn=s=>{const prior=s.monthlyBudgets.find(b=>b.month===month);const row={...(prior||D.meta()),month,amount:n};delete row.id;if(prior){D.touch(row);s.monthlyBudgets[s.monthlyBudgets.indexOf(prior)]=row;}else s.monthlyBudgets.push(row);const old=s.categoryBudgets.filter(b=>b.month===month);s.categoryBudgets=s.categoryBudgets.filter(b=>b.month!==month);for(const b of limits){const p=old.find(x=>x.categoryId===b.categoryId);D.assert(p||!D.find(s,'categories',b.categoryId).archived,'보관 카테고리에 새 한도를 만들 수 없습니다.');const r={...(p||D.meta()),month,...b};delete r.id;if(p)D.touch(r);s.categoryBudgets.push(r);}};if(D.sum(limits)>BigInt(n)){previewSave(fn,'카테고리 한도 합계가 전체 예산보다 큽니다. 그대로 저장할까요?',expected);return;}}
 if(e.type==='budget-copy'){D.assert(f.source!==month,'같은 월로 복사할 수 없습니다.');const source=state.monthlyBudgets.find(b=>b.month===f.source);D.assert(source,'원본 월에 예산이 없습니다.');const excluded=state.categoryBudgets.filter(b=>b.month===f.source&&D.find(state,'categories',b.categoryId).archived).map(b=>cat(b.categoryId));fn=s=>{const b=s.monthlyBudgets.find(b=>b.month===f.source),r={...D.meta(),month,amount:b.amount};delete r.id;s.monthlyBudgets=s.monthlyBudgets.filter(b=>b.month!==month);s.monthlyBudgets.push(r);s.categoryBudgets=s.categoryBudgets.filter(b=>b.month!==month);for(const b of s.categoryBudgets.filter(b=>b.month===f.source&&!D.find(s,'categories',b.categoryId).archived)){const x={...D.meta(),month,categoryId:b.categoryId,amount:b.amount};delete x.id;s.categoryBudgets.push(x);}};previewSave(fn,`${month}의 예산을 ${f.source} 설정으로 대체할까요?${excluded.length?' 제외: '+excluded.join(', '):''}`,expected);return;}
 if(e.type==='goal')fn=s=>{const old=e.id?D.find(s,'savingsGoals',e.id):null;D.assert(!old?.archived,'보관된 목표는 먼저 복원해 주세요.');D.saveNamed(s,'savingsGoals',{name:f.name,targetAmount:number(f.targetAmount,'목표 금액'),startDate:f.startDate,targetDate:f.targetDate,archived:old?.archived||false},e.id);};
 if(e.type==='entry')fn=s=>D.saveEntry(s,{goalId:e.context,date:f.date,kind:f.kind,amount:number(f.amount),memo:f.memo},e.id);
 if(e.type==='category')fn=s=>{const old=e.id?D.find(s,'categories',e.id):null;D.saveNamed(s,'categories',{name:f.name,kind:f.kind,archived:old?.archived||false,isDefault:old?.isDefault||false},e.id);};
 if(e.type==='payment')fn=s=>{const old=e.id?D.find(s,'paymentMethods',e.id):null;D.saveNamed(s,'paymentMethods',{name:f.name,type:f.type,paymentDay:f.type==='credit_card'&&f.paymentDay?Number(f.paymentDay):null,archived:old?.archived||false},e.id);};
 if(e.type==='rule'){const data={title:f.title,amount:number(f.amount),frequency:f.frequency,anchorDate:f.anchorDate,endDate:f.endDate||null,categoryId:f.categoryId||null,paymentMethodId:f.paymentMethodId||null,memo:f.memo};fn=(s,T)=>D.saveRule(s,data,e.id,T);const copy=structuredClone(state);fn(copy,D.today());D.validate(copy);const created=copy.transactions.filter(t=>!state.transactions.some(x=>x.id===t.id));previewSave(fn,e.id?`오늘까지의 도래 회차를 처리하고 ${D.dayAdd(D.today(),1)}부터 새 설정을 적용합니다. 개별 수정·건너뜀은 유지합니다. 저장할까요?`:`오늘까지 ${created.length}건, ${D.won(D.sum(created))}원이 생성됩니다. 저장할까요?`,expected);return;}
 if(e.type==='resume')fn=(s,T)=>D.resumeRule(s,e.id,f.date,T);
 if(fn)await commit(fn,{expected});
 }catch(err){error(err.message,err.field);}}
function download(data,prefix='acco-note-backup'){const text=JSON.stringify(data,null,2),blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;const time=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date()).replace(/[-: ]/g,'');a.download=`${prefix}-${time}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importFile(file){if(!file)return;try{D.assert(file.size<=30*1024*1024,'파일은 30MB 이하여야 합니다.');state=await DB.readStore();const parsed=importBackup(await file.text(),D.today()),copy=structuredClone(parsed.data),due=D.reconcile(copy),expected=DB.token(state),T=D.today();D.validate(copy);restoreFile={data:parsed.data,expected,T};const table=D.TABLES.map(t=>`<tr><th>${({categories:'카테고리',paymentMethods:'결제수단',transactions:'거래',refunds:'환불',savingsGoals:'저축 목표',savingsEntries:'저축 기록',monthlyBudgets:'월 예산',categoryBudgets:'분류 예산',recurrenceRules:'반복 설정',recurrenceVersions:'반복 버전',recurrenceOccurrences:'회차',recurrencePauses:'중지 구간'})[t]}</th><td>${state[t].length}</td><td>${parsed.data[t].length}</td></tr>`).join('');panel('백업 복원 미리보기',`<p>${esc(file.name)} · 생성 ${esc(parsed.exportedAt)}</p><p>KRW · Asia/Seoul · 버전 1 · 자동 확정 ${due}건</p><div class="data-table-wrap" tabindex="0"><table class="data-table"><thead><tr><th>항목</th><th>현재</th><th>가져올 데이터</th></tr></thead><tbody>${table}</tbody></table></div><p>현재 데이터를 전체 대체합니다. 복원 직전 사본 1개는 이 브라우저에 보존되며 외부 파일 백업을 대신하지 않습니다.</p>`,button('기존 데이터를 전체 대체','import-confirm',true)+button('취소','close'));}catch(e){error(e.message);}}
function changeMonth(m){D.assert(/^\d{4}-\d{2}$/.test(m)&&D.dateOK(m+'-01'),'이동할 수 없는 월입니다.');month=m;filters.from=m+'-01';filters.to=D.monthEnd(m);limit=20;selected.clear();closeEditor();render();}
function deleteRow(s,r,T){if(r.eventType==='refund'){s.refunds=s.refunds.filter(x=>x.id!==r.id);const t=D.find(s,'transactions',r.transactionId);if(t)D.touch(t);}else{let id=r.id;if(r.virtual)id=D.materialize(s,r,T).id;D.deleteTransaction(s,id);}}
document.addEventListener('submit',event=>{if(event.target.id==='edit-form'){event.preventDefault();saveForm();}if(event.target.id==='filters-form')event.preventDefault();});
function searchInput(event){if(event.target.id!=='search'||event.isComposing)return;const value=event.target.value;if(editing?.dirty)event.target.value=query;guarded(()=>{query=value;event.target.value=value;limit=20;selected.clear();bulk=false;refreshResults();});}
document.addEventListener('input',event=>{if(event.target.closest('#edit-form')&&editing){editing.dirty=true;event.target.removeAttribute('aria-invalid');}searchInput(event);});
document.addEventListener('compositionend',searchInput);

document.addEventListener('change',event=>{const input=event.target;if(input.id==='import-file'){guarded(()=>importFile(input.files[0]));return;}if(input.closest('#edit-form')&&editing){editing.dirty=true;const form=input.form;if(editing.type==='payment'&&input.name==='type')document.querySelector('#payment-day-field').hidden=input.value!=='credit_card';if(editing.type==='transaction'&&input.name==='kind'){const category=form.elements.categoryId;category.innerHTML=options('categories',input.value).map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('');form.elements.paymentMethodId.value='';form.elements.paymentMethodId.disabled=input.value==='income';notify('유형 변경으로 카테고리와 결제수단을 초기화했습니다.');}}
 if(input.closest('#filters-form')&&input.name==='period'){let from=D.today(),to=from;if(input.value==='week'){from=D.dayAdd(from,-((new Date(from+'T00:00:00Z').getUTCDay()+6)%7));to=D.dayAdd(from,6);}if(input.value==='month'){from=D.today().slice(0,7)+'-01';to=D.monthEnd(from.slice(0,7));}if(input.value!=='custom'){const form=input.form;form.elements.from._flatpickr.setDate(from);form.elements.to._flatpickr.setDate(to);}}});
document.addEventListener('click',event=>{if(loading)return;const target=event.target.closest('button,a,[data-action]');if(target?.matches('a[href^="#"]')){event.preventDefault();const dest=target.hash.slice(1);if(navs.some(([id])=>id===dest))guarded(()=>{closeEditor();page=dest;history.replaceState(null,'','#'+dest);bulk=false;selected.clear();showArchived=false;render();window.scrollTo(0,0);});return;}const rowEl=event.target.closest('[data-row]');if(rowEl){const id=rowEl.dataset.row;if(bulk){if(allRows().find(r=>r.id===id)?.eventType==='skipped')return;selected.has(id)?selected.delete(id):selected.add(id);render();document.querySelector(`[data-row="${CSS.escape(id)}"] input`)?.focus({preventScroll:true});}else guarded(()=>detail(id));return;}
 if(!target)return;
 const tab=target.dataset.ledgerTab,mt=target.dataset.manageTab,v=target.dataset.view;if(tab||mt||v){guarded(()=>{if(tab)ledgerTab=tab;if(mt)manageTab=mt;if(v){view=v;DB.transact(DB.token(state),s=>{s.settings.ledgerView=v;}).then(s=>state=s).catch(e=>error(e.message));}bulk=false;selected.clear();closeEditor();render();});return;}
 if(target.dataset.day){guarded(()=>{filters.from=filters.to=target.dataset.day;month=target.dataset.day.slice(0,7);view='list';render();});return;}
 for(const [attr,table] of [['goal','savingsGoals'],['category','categories'],['payment','paymentMethods']])if(target.dataset[attr]){guarded(()=>namedDetail(table,target.dataset[attr]));return;}
 if(target.dataset.rule){guarded(()=>ruleDetail(target.dataset.rule));return;}
 const a=target.dataset.action,id=target.dataset.id;if(!a)return;
 if(a==='confirm'){const fn=pending;pending=null;document.querySelector('#confirmation')?.remove();fn?.();return;}
 if(a==='cancel-confirm'){pending=null;document.querySelector('#confirmation')?.remove();return;}
 if(a==='close'){guarded(closeEditor);return;}
 if(a==='clear-end-date'){document.querySelector('[name=endDate]')?._flatpickr?.clear();if(editing)editing.dirty=true;return;}
 const run=async()=>{try{
 if(a==='add')openForm('transaction');else if(a==='transaction-edit')openForm('transaction',id);else if(a==='transaction-detail')detail(id);
 else if(a==='refund-form')openForm('refund',null,id);else if(a==='refund-edit')openForm('refund',id);
 else if(a==='goal-form')openForm('goal');else if(a==='goal-edit')openForm('goal',id);else if(a==='entry-form')openForm('entry',null,id);else if(a==='entry-edit')openForm('entry',id);
 else if(a==='category-form')openForm('category');else if(a==='category-edit')openForm('category',id);else if(a==='payment-form')openForm('payment');else if(a==='payment-edit')openForm('payment',id);
 else if(a==='rule-form')openForm('rule');else if(a==='rule-edit')openForm('rule',id);else if(a==='rule-resume')openForm('resume',id);
 else if(a==='budget-form')openForm('budget');else if(a==='budget-copy')openForm('budget-copy');
 else if(a==='prev-month'||a==='next-month'||a==='this-month')changeMonth(a==='this-month'?D.today().slice(0,7):D.monthAdd(month,a==='prev-month'?-1:1));
 else if(a==='filters'){filtersOpen=!filtersOpen;render();}
 else if(a==='apply-filters'){const form=document.querySelector('#filters-form'),fd=new FormData(form);const f=Object.fromEntries(fd);D.assert(D.dateOK(f.from)&&D.dateOK(f.to)&&f.from<=f.to,'올바른 조회 기간을 입력해 주세요.');D.assert(f.to<=D.dayAdd(f.from,3660),'한 번에 최대 10년까지 조회할 수 있습니다.');filters={from:f.from,to:f.to,kinds:fd.getAll('kinds'),categories:fd.getAll('categories'),payments:fd.getAll('payments'),states:fd.getAll('states')};filtersOpen=false;month=f.from.slice(0,7);limit=20;selected.clear();render();}
 else if(a==='reset-filters'){query='';filters={from:month+'-01',to:D.monthEnd(month),kinds:[],categories:[],payments:[],states:[]};limit=20;render();}
 else if(a==='bulk'){bulk=!bulk;selected.clear();closeEditor();render();}
 else if(a==='select-results'){filtered().filter(r=>r.eventType!=='skipped').forEach(r=>selected.add(r.id));render();}
 else if(a==='select-all'){const rows=filtered().slice(0,limit).filter(r=>r.eventType!=='skipped');if(rows.every(r=>selected.has(r.id)))selected.clear();else rows.forEach(r=>selected.add(r.id));render();document.querySelector('[data-action=select-all]')?.focus();}
 else if(a==='transaction-delete'||a==='delete-selected'){const rows=a==='transaction-delete'?[allRows().find(r=>r.id===id)||state.transactions.find(r=>r.id===id)]:filtered().filter(r=>selected.has(r.id));const expected=DB.token(state);ask(`선택한 ${rows.length}건을 삭제할까요? 연결 환불도 삭제되며 반복 회차는 건너뜀으로 남습니다.`,()=>commit((s,T)=>rows.forEach(r=>deleteRow(s,r,T)),{expected}));}
 else if(a==='refund-delete'){const expected=DB.token(state);ask('이 환불 기록을 삭제할까요?',()=>commit(s=>{const r=D.find(s,'refunds',id);D.assert(r,'환불이 변경되었습니다.');D.touch(D.find(s,'transactions',r.transactionId));s.refunds=s.refunds.filter(x=>x.id!==id);},{expected}));}
 else if(a==='entry-delete'){const expected=DB.token(state);ask('저축 기록을 삭제할까요? 이후 잔액이 음수가 되면 삭제할 수 없습니다.',()=>commit(s=>{const r=D.find(s,'savingsEntries',id),g=D.find(s,'savingsGoals',r.goalId);D.assert(!g.archived,'보관된 목표입니다.');D.touch(g);s.savingsEntries=s.savingsEntries.filter(r=>r.id!==id);},{expected}));}
 else if(a==='named-delete'||a==='named-archive'){const [table,rid]=id.split(':'),expected=DB.token(state);ask(a==='named-delete'?'이 항목을 삭제할까요?':'보관 상태를 변경할까요? 기존 기록은 유지됩니다.',()=>commit(s=>{const r=D.find(s,table,rid);D.assert(r,'항목이 변경되었습니다.');if(a==='named-delete'){D.assert(!D.referenced(s,table,rid),'사용 중인 항목은 삭제할 수 없습니다. 보관해 주세요.');s[table]=s[table].filter(x=>x.id!==rid);}else{r.archived=!r.archived;D.touch(r);}},{expected}));}
 else if(a==='budget-delete'){const expected=DB.token(state);ask(`${month}의 전체 예산과 카테고리 한도를 삭제할까요?`,()=>commit(s=>{s.monthlyBudgets=s.monthlyBudgets.filter(r=>r.month!==month);s.categoryBudgets=s.categoryBudgets.filter(r=>r.month!==month);},{expected}));}
 else if(a==='rule-stop'||a==='rule-delete'){const expected=DB.token(state),T=D.today();const copy=structuredClone(state);const due=D.reconcile(copy,T);ask(`도래 내역 ${due}건을 확정하고 앞으로의 예정 회차를 제거합니다. ${a==='rule-delete'?'삭제':'중지'}할까요?`,()=>commit((s,t)=>{D.assert(t===T,'날짜가 바뀌었습니다. 다시 확인해 주세요.');D.stopRule(s,id,a==='rule-delete',t);},{expected}));}
 else if(a==='unskip'){const expected=DB.token(state);ask('건너뜀을 취소하고 거래를 다시 생성할까요? 삭제된 환불은 복구되지 않습니다.',()=>commit((s,T)=>D.unskip(s,id,T),{expected}));}
 else if(a==='category-kind'){categoryKind=id;render();}else if(a==='archive-toggle'){showArchived=!showArchived;render();}
 else if(a==='category-ledger'||a==='payment-ledger'){const pid=id||editing?.detailId;page='ledger';ledgerTab='내역';view='list';filters={from:month+'-01',to:D.monthEnd(month),kinds:['expense'],categories:a==='category-ledger'?[pid]:[],payments:a==='payment-ledger'?[pid]:[],states:[]};query='';limit=20;closeEditor();render();}
 else if(a==='export'){state=await DB.readStore();download(exportBackup(state));}else if(a==='recovery'){state=await DB.readStore();D.assert(state.recovery,'복원 직전 백업이 없습니다.');download(state.recovery,'acco-note-before-import');}
 else if(a==='import-confirm'){const file=restoreFile;D.assert(file,'복원할 파일을 먼저 선택해 주세요.');ask('현재 데이터를 파일 내용으로 전체 대체합니다. 계속할까요?',async()=>{try{D.assert(file.T===D.today(),'날짜가 바뀌었습니다. 파일을 다시 선택해 주세요.');state=await DB.transact(file.expected,s=>D.reconcile(s),{restore:file.data});restoreFile=null;closeEditor();view=state.settings.ledgerView;render();notify('복원했습니다. 직전 사본은 백업 화면에서 다운로드할 수 있습니다.');}catch(e){error(e.message);}});}
 else if(a==='onboard')commit(s=>{s.meta.onboardingSeen=true;});
 }catch(e){error(e.message,e.field);}};
 guarded(run);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&editing&&!document.querySelector('.flatpickr-calendar.open'))guarded(closeEditor);});
window.addEventListener('beforeunload',e=>{if(editing?.dirty){e.preventDefault();e.returnValue='';}});
for(const q of ['(max-width:767px)','(max-width:1199px)'])matchMedia(q).addEventListener('change',()=>{const td=document.querySelector('.inline-detail-row>td');if(td)td.colSpan=[...td.closest('table').querySelectorAll('th')].filter(e=>getComputedStyle(e).display!=='none').length;});
window.addEventListener('hashchange',()=>guarded(()=>{const p=location.hash.slice(1);page=navs.some(([id])=>p===id)?p:'ledger';closeEditor();render();}));
async function reloadExternal(){try{const fresh=await DB.readStore();if(editing?.dirty){state=fresh;notify('다른 탭에서 변경되었습니다. 입력은 유지되며 저장 시 다시 확인합니다.');}else{state=fresh;render();}}catch(e){error(e.message);}}
async function start(){try{state=await DB.openStore(reloadExternal);view=state.settings.ledgerView;const p=location.hash.slice(1);page=navs.some(([id])=>p===id)?p:'ledger';render();setInterval(async()=>{if(loading||document.hidden)return;try{const fresh=await DB.syncDue();if(fresh.meta.sequence!==state.meta.sequence){if(editing?.dirty){state=fresh;notify('도래한 예정 내역을 확정했습니다. 저장 전 최신 내용을 확인해 주세요.');}else{state=fresh;render();}}}catch(e){notify(e.message);}},60000);}catch(e){main.innerHTML=`<section class="card empty"><h1>저장소를 열 수 없습니다</h1><p>${esc(e.message)}</p><p>브라우저의 사이트 저장 권한과 저장 공간을 확인한 뒤 다시 시도해 주세요.</p><button class="primary" onclick="location.reload()">다시 시도</button></section>`;}}
start();
